import { Group, PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Main plane – uses surface color
  const mainGeo = new PlaneGeometry(6, 0.5);
  const mainMat = new MeshBasicNodeMaterial({ color: '#0b0b10' });
  const mainMesh = new Mesh(mainGeo, mainMat);
  group.add(mainMesh);

  // Subtle divider at bottom edge
  const dividerGeo = new PlaneGeometry(6, 0.02);
  const dividerMat = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    opacity: 0.2,
    transparent: true,
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.y = -0.24; // just below main plane
  group.add(divider);

  // Accent edge on left side – starts hidden, appears on hover
  const accentGeo = new PlaneGeometry(0.06, 0.5);
  const accentMat = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0,
  });
  const accent = new Mesh(accentGeo, accentMat);
  accent.position.x = -2.97; // flush with left edge of main plane
  group.add(accent);

  // Hover animation – lift & accent edge
  const hoverTween = gsap.timeline({ paused: true });
  hoverTween
    .to(group.position, { y: 0.15, duration: 0.35, ease: 'power2.out' }, 0)
    .to(accentMat, { opacity: 1, duration: 0.25 }, 0);

  // Interaction handlers
  group.userData.handlers = {
    pointerover: () => {
      hoverTween.play();
    },
    pointerout: () => {
      hoverTween.reverse();
    },
    click: () => {
      // Press-down effect on click
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            duration: 0.2,
            ease: 'power2.out',
          });
        },
      });
      ctx.emit('hub-collection.select', {});
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    hoverTween.kill();
    mainGeo.dispose();
    mainMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  return group;
}
